"""폰잘알(PONJALAL) - Streamlit 실행 파일

GitHub 저장소 맨 위에 app.py 와 requirements.txt 두 파일만 올리고,
Streamlit Community Cloud 에서 Main file path 를 app.py 로 지정하면 실행됩니다.

- 수업, 연습, 용어, 문제 해결, 설정, 학습 기록은 이 파일만으로 작동합니다.
  (기록은 사용하는 브라우저에 저장됩니다.)
- 가족 대화, 사진 질문, 외국어 번역은 별도 서버가 필요합니다.
  서버가 있으면 아래 API_BASE 에 주소를 적으세요. 비워 두면 이 기능들은 쓸 수 없고
  안내 문구가 나옵니다.
- 화면 공유는 Streamlit 안의 화면에서는 브라우저가 허용하지 않아 시작할 수 없습니다.
"""
import base64
import json
import zlib

import streamlit as st
import streamlit.components.v1 as components

API_BASE = ""

_APP = ''

st.set_page_config(page_title="폰잘알", page_icon="📱", layout="centered", initial_sidebar_state="collapsed")
st.markdown(
    """
    <style>
    header, footer, #MainMenu, [data-testid="stToolbar"], [data-testid="stDecoration"] {display:none !important;}
    .block-container {padding:0 !important; max-width:480px !important;}
    iframe {border:0 !important; width:100% !important; height:100vh !important; display:block;}
    </style>
    """,
    unsafe_allow_html=True,
)


@st.cache_data(show_spinner=False)
def _page(api_base: str) -> str:
    html = zlib.decompress(base64.b64decode(_APP)).decode("utf-8")
    return html.replace("__API__", json.dumps(api_base))


components.html(_page(API_BASE), height=900, scrolling=True)
